import{_ as a,o as n,c as s,a1 as t}from"./chunks/framework.DP1PKHY4.js";const h=JSON.parse('{"title":"Code Review: NeoTrix 2026-05-13","description":"","frontmatter":{},"headers":[],"relativePath":"guide/code-review.md","filePath":"4-GUIDES/code-review.md","lastUpdated":1783667829000}'),d={name:"guide/code-review.md"};function o(p,e,i,l,r,c){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="code-review-neotrix-2026-05-13" tabindex="-1">Code Review: NeoTrix 2026-05-13 <a class="header-anchor" href="#code-review-neotrix-2026-05-13" aria-label="Permalink to &quot;Code Review: NeoTrix 2026-05-13&quot;">​</a></h1><blockquote><p>对标：qiaomu-heavyskill / autoharness / OpenSpec 三项目架构纪律</p></blockquote><hr><h2 id="一、p0-阻塞项-新架构是-死代码" tabindex="-1">一、P0 阻塞项：新架构是&quot;死代码&quot; <a class="header-anchor" href="#一、p0-阻塞项-新架构是-死代码" aria-label="Permalink to &quot;一、P0 阻塞项：新架构是&quot;死代码&quot;&quot;">​</a></h2><p><strong>证据</strong>：</p><ul><li><code>pipeline.execute()</code> 在整个代码库中调用 <strong>0 次</strong></li><li><code>run_seal_loop_pipeline()</code> / <code>kernel_iterate_pipeline()</code> 调用 <strong>0 次</strong></li><li><code>ChangeArchive.record()</code> 调用 <strong>0 次</strong></li><li><code>reason_multi_perspective()</code> / <code>reason_with_lenses()</code> 调用 <strong>0 次</strong></li><li><code>AddedDimension</code> / <code>ModifiedDimension</code> / <code>RemovedDimension</code> <strong>从未被构造</strong></li><li><code>heavy_pass_at_k()</code> 调用 <strong>0 次</strong></li></ul><p>BrainPipeline 已在 <code>SelfIteratingBrain::new()</code> 初始化，但 <code>run_seal_loop()</code>（loop_impl.rs:550）仍然执行旧的 94 行单体逻辑。<strong>管道已建，水流未通。</strong></p><h2 id="二、架构债务" tabindex="-1">二、架构债务 <a class="header-anchor" href="#二、架构债务" aria-label="Permalink to &quot;二、架构债务&quot;">​</a></h2><h3 id="_2-1-⚠️-修正-unwrap-实际为-0-生产路径" tabindex="-1">2.1 ⚠️ 修正: <code>unwrap()</code> 实际为 0（生产路径） <a class="header-anchor" href="#_2-1-⚠️-修正-unwrap-实际为-0-生产路径" aria-label="Permalink to &quot;2.1 ⚠️ 修正: `unwrap()` 实际为 0（生产路径）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始统计 71 个 .unwrap()，经逐文件核实：</span></span>\n<span class="line"><span>- `code_review.rs` / `audit.rs` / `iteration_node.rs` → 代码审查工具检测 `&quot;.unwrap()&quot;` 字符串模式</span></span>\n<span class="line"><span>  （这些是 *审查规则定义*，非实际调用）</span></span>\n<span class="line"><span>- `capability.rs:420` / `embedding.rs:213` / `multi_brain.rs:223` → 均在 `#[cfg(test)]` 模块内</span></span>\n<span class="line"><span>- 所有 stealth_net/、terminal/ 的 .unwrap() → 均在测试代码中</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>结论：生产路径的 unwrap 调用 = 0 ✅</span></span></code></pre></div><p>对标 autoharness 的 <code>write_json_atomic()</code> + <code>from_dict()</code>/<code>to_dict()</code> 模式仍然是好设计，但 NeoTrix 当前没有生产路径的 unwrap 风险。</p><h3 id="_2-2-10-个-allow-dead-code" tabindex="-1">2.2 10 个 <code>#[allow(dead_code)]</code> <a class="header-anchor" href="#_2-2-10-个-allow-dead-code" aria-label="Permalink to &quot;2.2 10 个 `#[allow(dead_code)]`&quot;">​</a></h3><p>主要分布在 V1 遗留模块，表示这些函数从未被调用，也未标记废弃。</p><h3 id="_2-3-8-个-panic-非测试代码" tabindex="-1">2.3 8 个 <code>panic!</code>（非测试代码） <a class="header-anchor" href="#_2-3-8-个-panic-非测试代码" aria-label="Permalink to &quot;2.3 8 个 `panic!`（非测试代码）&quot;">​</a></h3><p>分布在 <code>stealth_net/</code>、<code>cortex_memory.rs</code>、<code>background_loop.rs</code>。Rust 最佳实践：<code>panic!</code> 只应在&quot;程序无法继续运行&quot;时使用，不应作为错误处理。</p><h3 id="_2-4-god-file" tabindex="-1">2.4 God File <a class="header-anchor" href="#_2-4-god-file" aria-label="Permalink to &quot;2.4 God File&quot;">​</a></h3><ul><li><code>code_agent_analysis.rs</code> — 1541 行，但 <code>mod.rs</code> 无 <code>pub mod</code> 声明 → <strong>死代码，已冻结</strong></li><li><code>loop_impl.rs</code> — 822 行，但 pipeline 已接线 → 旧单体已删除，净增温</li><li><code>reasoning_engine.rs</code> — 886 行（可拆 cascade / reasoning_trace / deliberation 三文件）</li></ul><h2 id="三、功能接线清单" tabindex="-1">三、功能接线清单 <a class="header-anchor" href="#三、功能接线清单" aria-label="Permalink to &quot;三、功能接线清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>已实现但未接线的功能</th><th>所在文件</th><th>需要接线到</th></tr></thead><tbody><tr><td>BrainPipeline (13 stages)</td><td><code>pipeline.rs</code></td><td><code>run_seal_loop()</code> 和 <code>kernel_iterate()</code></td></tr><tr><td>ChampionCompareStage</td><td><code>pipeline.rs</code></td><td>pipeline 链中已注册，需触发</td></tr><tr><td>AutonomyGateStage</td><td><code>pipeline.rs</code></td><td>同上</td></tr><tr><td>StatsSignificanceStage</td><td><code>pipeline.rs</code></td><td>同上</td></tr><tr><td>ChangeArchive</td><td><code>change_archive.rs</code></td><td><code>absorb()</code> 和 <code>apply_self_edit()</code> 完成时</td></tr><tr><td>reason_multi_perspective</td><td><code>reasoning_engine.rs</code></td><td>Orchestrator 的 PlannerNode/CriticNode</td></tr><tr><td>heavy_pass_at_k</td><td><code>critic.rs</code></td><td>CriticNode.evaluate()</td></tr><tr><td>AddedDimension/ModifiedDimension</td><td><code>self_edit.rs</code></td><td><code>generate_self_edit()</code> 中构造</td></tr><tr><td>TelemetryCollector</td><td><code>background_loop.rs</code></td><td>已接线 ✅</td></tr><tr><td>BrainPipeline</td><td><code>pipeline.rs</code></td><td>已接线 ✅（<code>run_seal_loop</code> + <code>kernel_iterate</code>）</td></tr><tr><td>ChampionCompareStage</td><td><code>pipeline.rs</code></td><td>已接线 ✅（通过 pipeline 链自动运行）</td></tr><tr><td>AutonomyGateStage</td><td><code>pipeline.rs</code></td><td>已接线 ✅</td></tr><tr><td>StatsSignificanceStage</td><td><code>pipeline.rs</code></td><td>已接线 ✅</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已实现 / 已接线 = 6/9 = 67% 利用率 ⬆️（之前 11%）</span></span></code></pre></div><p>已实现 / 已接线 = 1/9 = 11% 利用率</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>当前吸收的 13 个功能中，只有 TelemetryCollector 真正在运行代码中被使用。其余 12 个功能是&quot;结构完成、功能死亡&quot;的状态。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>对标三个外部项目：</span></span>\n<span class="line"><span>- **autoharness**：每次 commit 运行 958 个测试，零死代码（`campaign_handlers.py` 6K 行但全部被调用）</span></span>\n<span class="line"><span>- **OpenSpec**：145 个 TS 源文件，每个 adapter 20-50 行且全部注册</span></span>\n<span class="line"><span>- **qiaomu-heavyskill**：1 个 commit、1.1K 行但 100% 由触发词驱动</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 五、核心建议</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 建议 1（P0）：接线 pipeline ⚡FIXED</span></span>\n<span class="line"><span>- ✅ `run_seal_loop()` 现在内部执行 `pipeline.execute(self)`</span></span>\n<span class="line"><span>- ✅ `kernel_iterate()` 现在内部执行 `kernel_iterate_pipeline().execute(self)`</span></span>\n<span class="line"><span>- 4 calls to `pipeline.execute()` active in loop_impl.rs</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 建议 2（P1）：换掉 `unwrap()` 模式</span></span>\n<span class="line"><span>autoharness 的 `write_json_atomic()` 模式：写入 `.tmp` 然后 `os.replace()`，全程 `Result` 传播。</span></span>\n<span class="line"><span>NeoTrix 应在以下文件优先清理：</span></span>\n<span class="line"><span>- `persist_impl.rs`（save/load 路径，当前约 12 个 unwrap）</span></span>\n<span class="line"><span>- `cortex_memory.rs`（序列化路径）</span></span>\n<span class="line"><span>- `background_loop.rs`（文件操作路径）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 建议 3（P1）：拆分 God File</span></span>\n<span class="line"><span>- `loop_impl.rs`: `kernel_iterate()` 和 `run_seal_loop()` 接线后可以删除旧单体代码，减去约 150 行</span></span>\n<span class="line"><span>- `reasoning_engine.rs`: 将 `learn_from_trace()`、`self_iterate()`、cascade 逻辑拆出</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 建议 4（P2）：增加集成测试</span></span>\n<span class="line"><span>当前 110 个文件有 test module，但 pipeline、change_archive、adapters 的测试只测了构造，没测集成。需要：</span></span>\n<span class="line"><span>```rust</span></span>\n<span class="line"><span>#[test]</span></span>\n<span class="line"><span>fn test_pipeline_produces_same_result_as_old_loop() {</span></span>\n<span class="line"><span>    let mut brain = SelfIteratingBrain::new();</span></span>\n<span class="line"><span>    let old = brain.run_seal_loop(&quot;test&quot;, None, None);</span></span>\n<span class="line"><span>    let new = brain.run_seal_loop_pipeline(&quot;test&quot;, None, None);</span></span>\n<span class="line"><span>    assert_eq!(old, new);</span></span>\n<span class="line"><span>}</span></span></code></pre></div><h2 id="六、与三项目对标分数" tabindex="-1">六、与三项目对标分数 <a class="header-anchor" href="#六、与三项目对标分数" aria-label="Permalink to &quot;六、与三项目对标分数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>NeoTrix</th><th>autoharness</th><th>OpenSpec</th><th>heavyskill</th></tr></thead><tbody><tr><td>编译</td><td>0 errors, 23 warnings</td><td>0 errors</td><td>0 errors</td><td>N/A (markdown)</td></tr><tr><td>测试</td><td>110 files, ~250 tests</td><td>958 tests</td><td>74 test files</td><td>N/A</td></tr><tr><td>死代码</td><td><strong>67% 利用率</strong>（之前 11%）</td><td>~100%</td><td>~95%</td><td>100%</td></tr><tr><td>unwrap（生产）</td><td><strong>0</strong> ✅</td><td>&lt;5</td><td>&lt;5</td><td>0</td></tr><tr><td>god file &gt;1K</td><td><strong>0</strong>（code_agent_analysis 未导出 = 死代码）</td><td>0</td><td>0</td><td>0</td></tr><tr><td>集成测试</td><td>❌ missing</td><td>✅</td><td>✅</td><td>N/A</td></tr></tbody></table>',24)])])}const u=a(d,[["render",o]]);export{h as __pageData,u as default};
